            const record = await FaceEmbeddings.create(
                imageHash,
                userId,
                imageType,
                face.faceImage,
                JSON.stringify(face.embedding),
                'facenet'
            );
            results.push(record);
        }

        return results;
    }
}

module.exports = { Model, User, FaceEmbeddings };

