const WebSocketServer = require('websocket').server;
const { addmessage,readchathistory } = require('./database/dbcrudmethods')
const clients = new Set();

function sendJson(connection, payload) {
    connection.sendUTF(JSON.stringify(payload));
}

function broadcast(payload) {
    for (const client of clients) {
        if (client.connected) {
            sendJson(client, payload);
        }
    }
}

function formatpayload(row){
    return {
        text: row.content,
        timestamp: row.timestamp,
        senderId: row.senderId,
    }
}

function attachChatServer(server) {
    const socketserver = new WebSocketServer({
        httpServer: server,
        autoAcceptConnections: false,
    });

    socketserver.on('request', (request) => {
        const connection = request.accept(null, request.origin);
        clients.add(connection);
        (async ()=>{
            const history = await readchathistory();
            sendJson(connection, {
                type:'history',
                messages: history.map(formatpayload),
            })
        })().catch((err)=>{
            sendJson(connection, {
                type:'error',
                text:"Chat history could not be found",
            })
        })
        connection.on('message', async (message) => {
            if (message.type !== 'utf8') {
                return;
            }

            try {
                const data = JSON.parse(message.utf8Data);
                const text = typeof data.text === 'string' ? data.text.trim() : "";
                const senderId = typeof data.senderId === 'string' ? data.senderId.trim() : "";

                if (!text || text.length > 1000) {
                    return sendJson(connection, {
                        type: "error",
                        text: "invalid message",
                    });
                }
                if (!senderId) {
                    return sendJson(connection, {
                        type: "error",
                        text: "missing sender id",
                    });
                }

                const savedMessage = await addmessage({
                    content: text,
                    timestamp: new Date(),
                    senderId,
                });
                broadcast({
                    type: 'message',
                    message: formatpayload(savedMessage.get({plain: true})),
                });
            } catch (error) {
                sendJson(connection, {
                    type: 'error',
                    text: 'invalid message format',
                });
            }
        });

        connection.on('close', (rescode, description) => {
            clients.delete(connection);
            console.log('websocket closed', rescode, description);
        });
    });

    return socketserver;
}

module.exports = { attachChatServer };

from fastapi import FastAPI, UploadFile, File, HTTPException
from deepface import DeepFace
import cv2
import numpy as np
import base64

app = FastAPI()

print("Loading Facenet model...")
DeepFace.build_model("Facenet")
print("Facenet model loaded successfully!")


@app.post("/embed")
async def get_embedding(file: UploadFile = File(...)):
    try:
        contents = await file.read()
        nparr = np.frombuffer(contents, np.uint8)
        img = cv2.imdecode(nparr, cv2.IMREAD_COLOR)

        result = DeepFace.represent(
            img_path=img,
            model_name="Facenet",
            enforce_detection=False
        )

        if len(result) > 0:
            return {"success": True, "embedding": result[0]["embedding"]}
        else:
            return {"success": False, "error": "No face detected"}

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/detect")
async def detect_faces(file: UploadFile = File(...)):
    try:
        contents = await file.read()
        nparr = np.frombuffer(contents, np.uint8)
        img = cv2.imdecode(nparr, cv2.IMREAD_COLOR)

        faces = DeepFace.extract_faces(img_path=img, enforce_detection=True)

        bboxes = []
        for face in faces:
            region = face["facial_area"]
            bboxes.append({
                "x": int(region["x"]),
                "y": int(region["y"]),
                "w": int(region["w"]),
                "h": int(region["h"]),
            })

        return {"success": True, "faces": bboxes}

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/embed-all")
async def embed_all_faces(file: UploadFile = File(...)):
    try:
        contents = await file.read()
        nparr = np.frombuffer(contents, np.uint8)
        img = cv2.imdecode(nparr, cv2.IMREAD_COLOR)

        faces = DeepFace.extract_faces(img_path=img, enforce_detection=True)

        results = []
        for face in faces:
            region = face["facial_area"]
            x, y, w, h = int(region["x"]), int(region["y"]), int(region["w"]), int(region["h"])

            cropped = img[y:y+h, x:x+w]

            repr_result = DeepFace.represent(
                img_path=cropped,
                model_name="Facenet",
                enforce_detection=False
            )

            if len(repr_result) > 0:
                _, buf = cv2.imencode('.jpg', cropped)
                face_b64 = base64.b64encode(buf.tobytes()).decode('utf-8')

                results.append({
                    "faceImage": face_b64,
                    "embedding": repr_result[0]["embedding"],
                    "bbox": {"x": x, "y": y, "w": w, "h": h},
                })

        return {"success": True, "faces": results}

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
